const state = {lang:new URLSearchParams(location.search).get("lang")==="zh"?"zh":"en",platform:"windows",page:"home",scenario:"normal",accepting:false,password:"Blue482X",revealed:false,modal:null,tab:"general",name:{windows:"Desk PC",mac:"My MacBook"},settings:{quality:"standard",reconnect:true,text:true,files:true},session:null,busy:false,details:false};
const t = key => strings[state.lang][key];
let returnFocus=null,toastTimer=null,connectTimer=null;
function notify(key){clearTimeout(toastTimer);$("toast").textContent=t(key);$("toast").hidden=false;toastTimer=setTimeout(()=>$("toast").hidden=true,2800);}
function chrome(){return state.platform==="mac"?'<span class="traffic" aria-hidden="true"><i></i><i></i><i></i></span><span>Local Remote Desktop</span>':'<img src="../../assets/brand/icon.svg" alt=""><span>Local Remote Desktop</span><span class="window-buttons" aria-hidden="true"><span>−</span><span>□</span><span>×</span></span>';}
function topbar(home=false){return `<div class="topbar">${home?'<span></span>':btn("home",icon("back")+t("back"),"quiet")}<div class="tools">${state.session&&state.page!=="session"?btn("session",t("connected"),"quiet"):""}${btn("settings",icon("gear")+t("settings"),"quiet")}</div></div>`;}
function home(){return `${topbar(true)}<div class="home-body"><h2>${t("question")}</h2><div class="choices">${["connect","accept"].map((role,i)=>btn(role,`<img src="../entry-review/${i?"accept":"initiate"}-connection.svg" alt="" draggable="false"><strong>${t(role)}</strong>`,"role")).join("")}</div>${state.accepting?`<div class="active-session"><span><i class="dot"></i> ${t("ongoing")}</span>${btn("accept",t("returnAccept"),"small")}</div>`:""}</div>`;}
function device(peer,index){return btn(`peer-${index}`,`<span class="device-art">${icon("monitor")}</span><span class="device-title"><strong>${escapeHtml(peer.name)}</strong><small>${peer.os} · ${t(peer.remembered?"remembered":"first")}</small></span><span class="availability"><i class="dot"></i>${t(peer.offline?"offline":"available")}</span>`,`device${peer.offline?" offline":""}`,peer.offline?'disabled':"");}
function connect(){return `${topbar()}<h2>${t("connect")}</h2><p class="description">${t("connectHint")}</p><div class="section-bar"><h3>${t("devices")}</h3><div class="tools">${btn("refresh",icon("refresh"),"icon-button quiet",`aria-label="${t("refresh")}"`)}${btn("add",icon("plus")+t("add"),"add")}</div></div><div class="scroll">${state.scenario==="empty"?`<div class="empty"><span class="device-art">${icon("monitor")}</span><strong>${t("empty")}</strong><p>${t("emptyHint")}</p></div>`:`<div class="list">${peers.map(device).join("")}</div>`}</div>`;}
function permissionRow(key,missing){return `<div class="permission-row ${missing?"missing":""}">${icon(missing?"alert":"check")}<span>${t(key)}</span>${missing?btn("permission",t("allow"),"small"): `<span class="allowed">${t("allowed")}</span>`}</div>`;}
function accept(){const mac=state.platform==="mac",captureMissing=mac&&state.scenario==="capture",inputMissing=mac&&state.scenario==="input",failed=state.scenario==="error";return `${topbar()}<h2>${t("accept")}</h2><p class="description">${t("acceptHint")}</p><div class="scroll"><div class="sharing-status ${state.accepting?"active":""}" role="status"><i class="dot"></i>${t(state.accepting?(state.scenario==="busy"?"inUse":"waiting"):"off")}</div><div class="local-device"><span class="device-art">${icon("monitor")}</span><div class="device-title"><small>${t("name")}</small><strong>${escapeHtml(state.name[state.platform])}</strong></div>${btn("name",t("change"),"small")}</div><div class="address-row"><div><span class="field-label">${t("localIp")}</span><span class="address">192.168.1.${mac?"12":"10"}</span></div>${btn("copy",t("copy"),"small")}</div><div class="password-block"><div class="password-heading"><strong>${t("password")}</strong>${btn("password",t("changePassword"),"small")}</div><div class="password-row"><span class="password">${state.revealed?escapeHtml(state.password):"••••••••"}</span>${btn("reveal",t(state.revealed?"hide":"show"),"small")}${btn("copy",t("copy"),"small")}</div><p class="help">${t("passwordHint")}</p></div>${mac?`<section class="permissions"><h3>${t("access")}</h3>${permissionRow("capture",captureMissing)}${permissionRow("input",inputMissing)}${captureMissing||inputMissing?`<p class="help">${t(captureMissing?"needCapture":"viewOnly")}</p>${btn("locate",t("locate"),"small")}`:""}</section>`:""}${failed?`<div class="notice" role="alert">${t("startError")}</div>${btn("details",t("details"),"quiet")}${state.details?`<p class="help">${t("portDetail")}</p>${btn("diagnostics",t("diagnostics"),"small")}`:""}`:""}</div><div class="action-footer">${state.accepting?btn("toggle-accept",t("stop"),"stop"):btn("toggle-accept",t("start"),"primary",captureMissing?"disabled":"")}</div>`;}
function settings(){const tab=state.tab;let body="";if(tab==="general")body=`<div class="setting-row"><label for="settings-language">${t("language")}</label><select id="settings-language"><option value="en" ${state.lang==="en"?"selected":""}>English</option><option value="zh" ${state.lang==="zh"?"selected":""}>简体中文</option></select></div>`;if(tab==="connection")body=`<div class="setting-row"><label for="quality-default">${t("quality")}</label><select id="quality-default">${qualities(state.settings.quality)}</select></div>${settingCheck("reconnect")}<p class="help">${t("defaults")}</p>`;if(tab==="clipboard")body=`${settingCheck("text")}${settingCheck("files")}<p class="help">${t("clipboardHint")}</p>`;if(tab==="about")body=`<section class="group"><h3>Local Remote Desktop</h3><p class="help">${t("aboutHint")}</p><p class="help">GPL-3.0-or-later</p></section>`;return `${topbar()}<h2>${t("settings")}</h2><p class="description"></p><div class="tabs" role="tablist">${["general","connection","clipboard","about"].map(k=>btn(`tab-${k}`,t(k),"",`role="tab" id="tab-${k}" aria-controls="settings-panel" aria-selected="${tab===k}" tabindex="${tab===k?0:-1}"`)).join("")}</div><div class="scroll" id="settings-panel" role="tabpanel" aria-labelledby="tab-${tab}">${body}</div>`;}
function settingCheck(key){return `<div class="setting-row"><label for="setting-${key}">${t(key)}</label><input id="setting-${key}" data-setting="${key}" type="checkbox" ${state.settings[key]?"checked":""}></div>`;}
function qualities(value){return ["smooth","standard","high"].map(k=>`<option value="${k}" ${k===value?"selected":""}>${t(k)}</option>`).join("");}
function session(){return `${topbar()}<div class="session"><div class="session-toolbar"><strong>${escapeHtml(state.session?.name||state.session?.ip||"192.168.1.24")}</strong><select id="session-quality" aria-label="${t("quality")}">${qualities(state.session?.quality||state.settings.quality)}</select>${btn("disconnect",t("disconnect"),"small")}</div><div class="mock-desktop"><div class="mock-window"><strong>${t("desktop")}</strong><p>${t("desktopHint")}</p></div></div><p class="session-caption"><i class="dot"></i> ${t("connected")}</p>${state.scenario==="transfer"?`<div class="transfer"><div>${t("file")}<small class="field-label">${t("transfer")}</small><progress value="64" max="100" aria-label="${t("transfer")}"></progress></div>${btn("cancel-transfer",t("cancel"),"small")}</div>`:""}</div>`;}
function render(){document.documentElement.lang=state.lang==="zh"?"zh-CN":"en";$("language").value=state.lang;$("platform").value=state.platform;$("app").classList.toggle("mac",state.platform==="mac");$("review-title").textContent=t("review");for(const [id,key] of [["language-label","language"],["platform-label","platform"],["size-label","size"],["scenario-label","scenario"],["sample-hint","sample"],["disclosure","disclosure"],["design-link","notes"],["previous-link","previous"]])$(id).textContent=t(key);$("review-pages").innerHTML=["home","connect","accept","settings"].map(k=>btn(`page-${k}`,t(k),"",state.page===k?'aria-current="page"':"")).join("");$("chrome").innerHTML=chrome();$("screen").className=`screen ${state.page}`;$("screen").innerHTML=({home,connect,accept,settings,session}[state.page])();const scenarios={normal:"normal",empty:"emptyState",pair:"pairState",capture:"captureState",input:"inputState",error:"errorState",busy:"busyState",transfer:"transferState"};$("scenario").innerHTML=Object.entries(scenarios).map(([v,k])=>`<option value="${v}" ${state.scenario===v?"selected":""}>${t(k)}</option>`).join("");renderModal();}
function navigate(page){if(state.busy)return;if(page==="connect"&&state.session)page="session";state.page=page;render();$("screen").querySelector("h2,button")?.focus({preventScroll:true});}
function openModal(kind,peer=null){returnFocus=document.activeElement;state.modal={kind,peer,ip:peer?.ip||"",password:peer?.remembered?"Blue482X":"",remember:!!peer?.remembered,draft:kind==="name"?state.name[state.platform]:"",quality:state.settings.quality,error:""};renderModal();$("overlay").querySelector("input,button")?.focus();}
function closeModal(){if(state.busy)return;state.modal=null;renderModal();if(returnFocus?.isConnected)returnFocus.focus();else $("screen").querySelector("button")?.focus();}
function renderModal(){const layer=$("overlay"),m=state.modal;layer.hidden=!m;$("screen").inert=!!m;$("review-pages").inert=!!m;if(!m){layer.innerHTML="";return;}let title=t(m.kind==="target"?"join":m.kind==="password"?"changePassword":m.kind==="name"?"name":m.kind==="receive-conflict"?"endRemote":"conflict"),body="";if(m.kind==="target")body=`${m.peer?`<div class="peer-summary"><span class="device-art">${icon("monitor")}</span><div class="device-title"><strong>${escapeHtml(m.peer.name)}</strong><small>${m.peer.os} · ${m.peer.ip}</small></div></div>`:`<label class="field" for="target-ip">${t("targetIp")}</label><input id="target-ip" data-draft="ip" class="full" type="text" inputmode="decimal" autocomplete="off" placeholder="192.168.1.24" value="${escapeHtml(m.ip)}">`}<label class="field" for="target-password">${t("targetPassword")}</label><input id="target-password" data-draft="password" class="full" type="password" autocomplete="off" value="${escapeHtml(m.password)}" aria-describedby="form-error"><label class="check"><input id="remember-password" type="checkbox" ${m.remember?"checked":""}>${t("remember")}</label>${m.peer?.remembered?btn("forget",t("forget"),"quiet"):""}<label class="field" for="target-quality">${t("quality")}</label><select id="target-quality" class="full">${qualities(m.quality)}</select>`;
  if(m.kind==="password")body=`<label class="field" for="new-password">${t("newPassword")}</label><div class="generate-row"><input id="new-password" data-draft="draft" type="text" maxlength="8" autocomplete="off" value="${escapeHtml(m.draft)}" aria-describedby="password-help form-error">${btn("generate",t("generate"),"generate")}</div><p class="help" id="password-help">${t("passwordHelp")}</p>${state.accepting?`<p class="notice">${t("saveHint")}</p>`:""}`;
  if(m.kind==="name")body=`<label class="field" for="local-name">${t("name")}</label><input id="local-name" class="full" data-draft="draft" type="text" maxlength="64" value="${escapeHtml(m.draft)}">${btn("system-name",t("systemName"),"quiet")}`;
  if(m.kind==="receive-conflict")body=`<p class="help">${t("endRemoteHint")}</p>`;
  if(m.kind==="conflict")body=`<p class="help">${t("conflictHint")}</p>`;
  layer.innerHTML=`<section class="sheet" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="sheet-header"><h2 id="dialog-title">${title}</h2>${btn("close",icon("close"),"icon-button",`aria-label="${t("close")}" ${state.busy?"disabled":""}`)}</header><div class="sheet-body">${body}<p id="form-error" class="error" role="alert">${m.error?t(m.error):""}</p></div><footer class="sheet-footer">${btn("close",t("cancel"),"",state.busy?"disabled":"")}${btn("submit",t(state.busy?"joining":m.kind==="target"?"join":m.kind==="conflict"?"stopConnect":m.kind==="receive-conflict"?"disconnectAccept":"save"),"primary",state.busy?'disabled aria-busy="true"':"")}</footer></section>`;
  if(state.busy)layer.querySelectorAll("input,select,button").forEach(el=>el.disabled=true);
}
function validIp(value){const p=value.split(".");if(p.length!==4||!p.every(x=>/^\d{1,3}$/.test(x)&&Number(x)<=255))return false;const [a,b]=p.map(Number);return a===10||a===172&&b>=16&&b<=31||a===192&&b===168;}
function beginConnection(target){state.busy=true;renderModal();connectTimer=setTimeout(()=>{state.busy=false;state.modal=null;state.session={...target};state.page="session";render();$("screen").querySelector("button")?.focus();},700);}
function submit(){const m=state.modal;if(!m||state.busy)return;if(m.kind==="target"){m.ip=m.ip.trim();if(!validIp(m.ip)){m.error="ipError";renderModal();$("target-ip")?.focus();return;}if(m.password!=="Blue482X"||state.scenario==="pair"){m.error="pairError";state.scenario="normal";renderModal();$("target-password").focus();return;}const target={ip:m.ip,name:m.peer?.name,quality:m.quality};if(state.accepting){state.modal={kind:"conflict",target};renderModal();$("overlay").querySelector("button").focus();return;}beginConnection(target);return;}
  if(m.kind==="receive-conflict"){state.session=null;state.accepting=true;state.modal=null;render();return;}
  if(m.kind==="conflict"){state.accepting=false;beginConnection(m.target);return;}
  if(m.kind==="password"){if(!/^[\x21-\x7E]{8}$/.test(m.draft)){m.error="passwordError";renderModal();$("new-password").focus();return;}state.password=m.draft;state.accepting=false;state.revealed=false;}
  if(m.kind==="name"){if(!m.draft.trim()){m.error="nameError";renderModal();$("local-name").focus();return;}state.name[state.platform]=m.draft.trim();}
  state.modal=null;render();notify("saved");$("screen").querySelector("button")?.focus();
}
document.addEventListener("input",e=>{if(state.modal&&e.target.dataset.draft)state.modal[e.target.dataset.draft]=e.target.value;});
document.addEventListener("change",e=>{const el=e.target;if(el.id==="language"||el.id==="settings-language"){state.lang=el.value;render();$(el.id)?.focus();}else if(el.id==="platform"){clearTimeout(connectTimer);state.busy=false;state.platform=el.value;state.accepting=false;state.session=null;state.modal=null;state.page="home";render();}else if(el.id==="size")$("app").classList.toggle("small-frame",el.value==="small");else if(el.id==="scenario"){clearTimeout(connectTimer);state.busy=false;state.modal=null;state.scenario=el.value;state.details=false;if(["capture","input"].includes(el.value))state.platform="mac";state.accepting=el.value==="busy";state.session=null;if(["empty","pair"].includes(el.value))state.page="connect";else if(["capture","input","error","busy"].includes(el.value))state.page="accept";else if(el.value==="transfer"){state.page="session";state.session={...peers[0],quality:state.settings.quality};}render();}else if(el.id==="remember-password")state.modal.remember=el.checked;else if(el.id==="target-quality")state.modal.quality=el.value;else if(el.id==="quality-default")state.settings.quality=el.value;else if(el.id==="session-quality")state.session.quality=el.value;else if(el.dataset.setting)state.settings[el.dataset.setting]=el.checked;});
document.addEventListener("click",e=>{const el=e.target.closest("button[data-action]");if(!el||el.disabled||state.busy)return;const action=el.dataset.action;if(action.startsWith("page-")){state.modal=null;navigate(action.slice(5));}else if(["home","connect","accept","settings","session"].includes(action))navigate(action);else if(action.startsWith("peer-"))openModal("target",peers[Number(action.slice(5))]);else if(action==="add")openModal("target");else if(["password","name"].includes(action))openModal(action);else if(action==="close")closeModal();else if(action==="submit")submit();else if(action==="reveal"){state.revealed=!state.revealed;render();$("screen").querySelector('[data-action="reveal"]').focus();}else if(action==="generate"){state.modal.draft="Lime482Q";$("new-password").value=state.modal.draft;$("new-password").focus();}else if(action==="system-name"){state.modal.draft=state.platform==="mac"?"My MacBook":"Desk PC";$("local-name").value=state.modal.draft;}else if(action==="forget"){state.modal.password="";state.modal.remember=false;renderModal();$("target-password").focus();notify("forgotten");}else if(action==="toggle-accept"){if(state.session&&!state.accepting){openModal("receive-conflict");return;}if(state.accepting)state.accepting=false;else if(state.scenario!=="error")state.accepting=true;else state.details=true;render();$("screen").querySelector('[data-action="toggle-accept"]').focus();}else if(action==="details"){state.details=!state.details;render();}else if(action==="disconnect"){state.session=null;state.page="connect";state.scenario="normal";render();notify("disconnected");}else if(action==="cancel-transfer"){state.scenario="normal";render();notify("cancelled");}else if(["copy","diagnostics"].includes(action))notify("copied");else if(action==="permission")notify("permission");else if(action==="locate")notify("located");else if(action==="refresh"){notify("refreshed");}});
document.addEventListener("keydown",e=>{if(e.target.getAttribute("role")==="tab"&&["ArrowLeft","ArrowRight","Home","End"].includes(e.key)){e.preventDefault();const tabs=["general","connection","clipboard","about"];const i=tabs.indexOf(state.tab);state.tab=tabs[e.key==="Home"?0:e.key==="End"?3:(i+(e.key==="ArrowRight"?1:3))%4];render();$("tab-"+state.tab).focus();return;}if(!state.modal)return;if(e.key==="Escape"){e.preventDefault();closeModal();}else if(e.key==="Enter"&&e.target.tagName==="INPUT"){e.preventDefault();submit();}else if(e.key==="Tab"){const controls=[...$("overlay").querySelectorAll("button,input,select")].filter(el=>!el.disabled);if(!controls.length){e.preventDefault();return;}const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
// Tab activation uses the same full-screen settings hierarchy on both platforms.
document.addEventListener("click",e=>{const action=e.target.closest("button")?.dataset.action;if(action?.startsWith("tab-")){state.tab=action.slice(4);render();$("tab-"+state.tab).focus();}});
render();
